<?php

declare(strict_types=1);

namespace TypedPress\Wp;

/**
 * Applies tp/app/migrations/NNNN_<name>.sql (MySQL dialect, generated by `typedpress build`) in
 * filename order, recorded in {prefix}tp__migrations keyed by (app, id): ids like `0001_init`
 * repeat across apps, so each app sees only its own rows (see `ledger` for converting an old one). `{prefix}` in the SQL is replaced by
 * $wpdb->prefix. MySQL DDL commits implicitly, so each statement that succeeds is recorded as
 * `<id>:<n>` and skipped on the retry; the file's own id is recorded (and the progress rows removed)
 * once every statement has run. A file that failed half way therefore resumes where it stopped.
 *
 * A statement can commit without its marker (the process died between the two). The retry then
 * fails on it ("already exists") and keeps failing, by design: nothing guesses that the existing
 * object is the right one. The operator checks it and records the step with
 * `wp typedpress migrate --mark-applied <id>:<n>` (see `markApplied`); the next request resumes after it.
 *
 * After migrating, every TypedPress table plus wp_posts/wp_postmeta must be InnoDB: TypedPress's request
 * transactions depend on it (§3.3), so every migration path refuses otherwise.
 *
 * A file's row records `sql`, the SHA-256 of the file as it was applied (before `{prefix}` is
 * replaced), so what ran can be compared with a build's files later. Rows written before the column
 * existed, and step rows, have none: they count by id only.
 */
final class Migrator
{

    /** @param array<string, int> $drops `--drop` confirmations for the schema check (SchemaCheck::drops) */
    public function __construct(
        private readonly Connection $db,
        private readonly string $dir,
        private readonly \TypedPress\Schema $schema,
        private readonly array $drops = [],
    ) {
    }

    /** The statements of a migration file: split on the compiler's `--> statement-breakpoint` lines. */
    public static function statements(string $sql): array
    {
        $parts = preg_split('/-->[ \t]*statement-breakpoint/', $sql) ?: [];

        return array_values(array_filter(array_map('trim', $parts), static fn ($s) => $s !== ''));
    }

    /**
     * Records `<id>:<n>` (statement n of migration id) as applied without running it, for a statement
     * whose effect is already in the database. Only the next pending statement can be marked.
     */
    public function markApplied(string $step): void
    {
        if (!preg_match('/^(.+):([1-9]\\d*)$/', $step, $m)) {
            throw \TypedPress\HttpError::invalidInput('--mark-applied takes <migration id>:<statement number>, e.g. 0002_update:1', '/mark-applied');
        }
        [, $id, $n] = $m;
        // Marking a step skips it, so the tables it would touch are checked as migrate() checks them.
        $this->guardBindings();
        ['migrations' => $migrations, 'done' => $done] = $this->read();
        $this->guardAdoptions($migrations, $done);
        // Only a migration file of this app, named exactly as `pending()` names it (no paths).
        $files = array_map(static fn (string $f): string => basename($f, '.sql'), glob($this->dir . '/*.sql') ?: []);
        if (!in_array($id, $files, true)) {
            throw new \TypedPress\HttpError(409, 'not_pending', "$id is not a pending migration of this app");
        }
        $file = $this->dir . '/' . $id . '.sql';
        $ledger = $this->ledger();
        $done = array_flip($this->done());
        if (!is_file($file) || isset($done[$id])) {
            throw new \TypedPress\HttpError(409, 'not_pending', "$id is not a pending migration of this app");
        }
        $count = count(self::statements((string) file_get_contents($file)));
        $next = 1;
        while (isset($done["$id:$next"])) {
            $next++;
        }
        if ((int) $n !== $next || $next > $count) {
            throw new \TypedPress\HttpError(409, 'not_pending', "the next pending statement of $id is $next of $count; only that one can be marked");
        }
        $this->db->run("INSERT INTO `$ledger` (`app`, `id`, `applied_at`) VALUES (?, ?, ?)", [$this->schema->name(), $step, gmdate('Y-m-d\\TH:i:s.000\\Z')]);
    }

    /**
     * What {@see migrate()} would run, after the same schema check, without changing anything: no
     * DDL, no ledger row, and an old unkeyed ledger is read, not converted. Per pending migration its
     * id, the hash recorded once it applies, and the statements still to run (numbered from 1 in the
     * file). Throws SchemaRefused exactly when migrate() would.
     *
     * @return list<array{id: string, sql: string, statements: list<int>}>
     * @throws SchemaRefused
     */
    public function plan(): array
    {
        $this->guardBindings();
        ['migrations' => $migrations, 'hashes' => $hashes, 'done' => $done] = $this->read();
        $this->check($migrations, $done);
        try {
            $this->preflightAdoptions($migrations, $done);
        } catch (DbError $e) {
            throw new SchemaRefused([['code' => 'adoption_mismatch', 'name' => 'existingTable', 'rows' => 0, 'message' => $e->getMessage(),
                'fix' => "Make the existing table match the declaration's columns, indexes, keys and integer types, or change the declaration; nothing was changed."]]);
        }
        $plan = [];
        foreach ($migrations as $id => $statements) {
            if (isset($done[$id])) {
                continue;
            }
            $left = array_values(array_filter(array_keys($statements), static fn (int $i): bool => !isset($done[$id . ':' . ($i + 1)])));
            $plan[] = ['id' => (string) $id, 'sql' => $hashes[$id], 'statements' => array_map(static fn (int $i): int => $i + 1, $left)];
        }

        return $plan;
    }

    /**
     * This app's migration files (id => statements, `{prefix}` replaced; id => hash of the file) and
     * what the ledger records as done, read without changing anything: a ledger from before rows were
     * keyed by app is read as this app's when this app is its one owner (as ledger() would convert it).
     *
     * @return array{migrations: array<string, list<string>>, hashes: array<string, string>, done: array<string, int>}
     */
    private function read(): array
    {
        $files = glob($this->dir . '/*.sql') ?: [];
        sort($files, SORT_STRING);
        $migrations = [];
        $hashes = [];
        foreach ($files as $file) {
            $id = basename($file, '.sql');
            $raw = (string) file_get_contents($file);
            $hashes[$id] = hash('sha256', $raw);
            $migrations[$id] = self::statements(str_replace('{prefix}', $this->db->prefix(), $raw));
        }

        return ['migrations' => $migrations, 'hashes' => $hashes, 'done' => array_flip($this->keyed() ? $this->done() : $this->unkeyedDone())];
    }

    /**
     * The deploy-time schema check (spec §2.9): every pending statement that could lose rows or leave
     * them without a required value is measured first, across all pending files, so a refusal leaves
     * the tables, the rows and the ledger untouched. A file that stopped part way has steps that
     * already ran: their renames are replayed (not measured), so the checks after them find the
     * tables and columns under their new names.
     *
     * @param array<string, list<string>> $migrations
     * @param array<string, int> $done
     */
    private function check(array $migrations, array $done): void
    {
        $pending = [];
        $applied = [];
        foreach ($migrations as $id => $statements) {
            foreach (isset($done[$id]) ? [] : $statements as $i => $statement) {
                if (isset($done[$id . ':' . ($i + 1)])) {
                    $applied[] = $statement;
                } else {
                    $pending[$id][] = $statement;
                }
            }
        }
        $this->guardAdoptions($migrations, $done);
        (new SchemaCheck($this->db, $this->drops))->check($pending, $applied);
    }

    /** @return list<string> ids applied by this call */
    public function migrate(): array
    {
        $this->guardBindings();
        $this->requireCompatibleTables();
        $app = $this->schema->name();
        ['migrations' => $migrations, 'hashes' => $hashes, 'done' => $done] = $this->read();
        // The ledger is only converted below, once the check has passed.
        $this->check($migrations, $done);
        try {
            $this->preflightAdoptions($migrations, $done);
        } catch (DbError $e) {
            throw new \RuntimeException($e->getMessage(), 0, $e);
        }
        $ledger = $this->ledger();
        $done = array_flip($this->done());
        $applied = [];
        foreach ($migrations as $id => $statements) {
            if (isset($done[$id])) {
                continue;
            }
            foreach ($statements as $i => $statement) {
                $step = $id . ':' . ($i + 1);
                if (isset($done[$step])) {
                    continue;
                }
                try {
                    $this->execute($statement);
                } catch (DbError $e) {
                    throw new \RuntimeException("Migration $id failed at statement " . ($i + 1) . ': ' . $e->getMessage(), 0, $e);
                }
                $this->db->run("INSERT INTO `$ledger` (`app`, `id`, `applied_at`) VALUES (?, ?, ?)", [$app, $step, gmdate('Y-m-d\TH:i:s.000\Z')]);
            }
            $this->db->run("INSERT INTO `$ledger` (`app`, `id`, `applied_at`, `sql`) VALUES (?, ?, ?, ?)", [$app, $id, gmdate('Y-m-d\TH:i:s.000\Z'), $hashes[$id]]);
            $this->db->run("DELETE FROM `$ledger` WHERE `app` = ? AND `id` LIKE ?", [$app, $this->db->wpdb()->esc_like($id . ':') . '%']);
            $applied[] = $id;
        }

        $this->requireCompatibleTables();
        return $applied;
    }

    /**
     * Runs one migration statement. On the SQLite Database Integration driver, renames take another
     * route: it has no RENAME TABLE (the table is copied under its new name, rows and auto-increment
     * included, and the old one dropped, in one transaction), and its RENAME COLUMN loses the values
     * (it runs as CHANGE COLUMN with the definition the compiler recorded).
     */
    private function execute(string $statement): void
    {
        $sql = SchemaCheck::sql($statement);
        $check = SchemaCheck::parse($statement);
        if (!$this->db->sqlite() || ($check['check'] ?? null) !== 'rename') {
            $this->db->run($sql);

            return;
        }
        if (isset($check['column'])) {
            // The statement names the table as it is when it runs (an earlier rename may have moved it);
            // the check names it as it was before the plan.
            preg_match('/^ALTER TABLE (`(?:[^`]|``)+`)/', $sql, $m);
            $this->db->run("ALTER TABLE {$m[1]} CHANGE COLUMN `" . str_replace('`', '``', (string) $check['column']) . '` ' . $check['definition']);

            return;
        }
        $from = '`' . str_replace('`', '``', (string) $check['table']) . '`';
        $to = '`' . str_replace('`', '``', (string) $check['to']) . '`';
        $create = array_values($this->db->run("SHOW CREATE TABLE $from")[0])[1];
        $dbh = $this->db->wpdb()->dbh;
        $dbh->query('START TRANSACTION');
        try {
            $dbh->query((string) preg_replace('/^CREATE TABLE `(?:[^`]|``)+`/', "CREATE TABLE $to", $create));
            $dbh->query("INSERT INTO $to SELECT * FROM $from");
            $dbh->query("DROP TABLE $from");
            $dbh->query('COMMIT');
        } catch (\Throwable $e) {
            $dbh->query('ROLLBACK');
            throw new DbError($e->getMessage() . " [$sql]", 0);
        }
    }

    private function requireCompatibleTables(): void
    {
        $bad = $this->nonInnoDb();
        if ($bad !== []) {
            throw new \RuntimeException('TypedPress needs InnoDB tables with utf8mb4; these are incompatible: ' . implode(', ', $bad));
        }
    }

    /** A table the app binds but didn't create must be this site's, before anything reads it. */
    private function guardBindings(): void
    {
        foreach ($this->schema->collections() as $collection => $spec) {
            if (isset($spec['existingTable'])) {
                Guard::table((string) $spec['existingTable'], $this->db->prefix(), Guard::names((string) $collection, $spec));
            }
        }
    }

    /**
     * Every pending adoption against the live table (declared indexes, foreign keys, integer types and
     * a `SELECT <columns> LIMIT 0` probe), before any DDL or ledger write, even across tables and
     * files. Reads only, so plan() runs it too.
     *
     * @param array<string, list<string>> $migrations
     * @param array<string, int> $done
     * @throws DbError naming the migration and statement
     */
    private function preflightAdoptions(array $migrations, array $done): void
    {
        foreach ($migrations as $id => $statements) {
            foreach (isset($done[$id]) ? [] : $statements as $i => $statement) {
                if (!str_starts_with($statement, '-- typedpress-adopt ') || isset($done[$id . ':' . ($i + 1)])) {
                    continue;
                }
                try {
                    $this->validateAdoption($statement);
                    $this->db->run($statement);
                } catch (DbError $e) {
                    throw new DbError("Migration $id failed at statement " . ($i + 1) . ': ' . $e->getMessage(), 0);
                }
            }
        }
    }

    /**
     * Guards (guardAdoption) every adoption record a pending step relies on: one still pending, and
     * one already applied whose table a pending statement names, so a table adopted by an earlier
     * runtime is checked again before a later statement alters or drops it, even once no collection
     * binds it. Generated statements quote every table name.
     *
     * @param array<string, list<string>> $migrations
     * @param array<string, int> $done
     */
    private function guardAdoptions(array $migrations, array $done): void
    {
        $pending = [];
        foreach ($migrations as $id => $statements) {
            foreach (isset($done[$id]) ? [] : $statements as $i => $statement) {
                if (!isset($done[$id . ':' . ($i + 1)])) {
                    $pending[] = $statement;
                }
            }
        }
        foreach ($migrations as $id => $statements) {
            foreach ($statements as $i => $statement) {
                if (!str_starts_with($statement, '-- typedpress-adopt ')) {
                    continue;
                }
                $applied = isset($done[$id]) || isset($done[$id . ':' . ($i + 1)]);
                $quoted = '`' . str_replace('`', '``', (string) self::adoption($statement)['table']) . '`';
                $touched = static fn (): bool => array_filter($pending, static fn (string $s): bool => $s !== $statement && str_contains($s, $quoted)) !== [];
                if (!$applied || $touched()) {
                    $this->guardAdoption($statement, $migrations);
                }
            }
        }
    }

    /** The JSON of a `-- typedpress-adopt` line. */
    private static function adoption(string $statement): array
    {
        return json_decode(explode("\n", substr($statement, strlen('-- typedpress-adopt ')), 2)[0], true, flags: JSON_THROW_ON_ERROR);
    }

    /**
     * Refuses an adoption record's table unless this site may bind it, on the record's own terms: a
     * later migration of the same deploy may drop the collection that binds it now. A Zero 0.8
     * table's digest is over the name it was adopted under: the record's `name`, else (records from
     * before it) a collection binding the table now or a later drop check of it.
     *
     * @param array<string, list<string>> $migrations every migration's statements, by id
     */
    private function guardAdoption(string $statement, array $migrations): void
    {
        $expected = self::adoption($statement);
        $table = $expected['table'];
        $names = is_string($expected['name'] ?? null) ? [$expected['name']] : [];
        foreach ($this->schema->collections() as $collection => $spec) {
            if (($spec['existingTable'] ?? null) === $table) {
                $names = [...$names, ...Guard::names((string) $collection, $spec)];
            }
        }
        foreach ($migrations as $statements) {
            foreach ($statements as $later) {
                $check = SchemaCheck::parse($later);
                if (($check['check'] ?? null) === 'drop' && !isset($check['column']) && ($check['table'] ?? null) === $table) {
                    $names = [...$names, ...array_filter([$check['adoptedAs'] ?? null, $check['name'] ?? null], 'is_string')];
                }
            }
        }
        Guard::table((string) $table, $this->db->prefix(), array_values(array_unique($names)));
    }

    /** Adoption records compiler names in the snapshot; verify those names before recording the step. */
    private function validateAdoption(string $statement): void
    {
        $expected = self::adoption($statement);
        $table = $expected['table'];
        $indexes = [];
        foreach ($this->db->run('SELECT INDEX_NAME AS n, NON_UNIQUE AS u, COLUMN_NAME AS c, SUB_PART AS p FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? ORDER BY INDEX_NAME, SEQ_IN_INDEX', [$table]) as $row) {
            $indexes[$row['n']][] = $row;
        }
        foreach ($expected['indexes'] as $index) {
            $actual = $indexes[$index['name']] ?? [];
            if (array_column($actual, 'c') !== $index['columns']
                || array_filter($actual, static fn (array $r): bool => (int) $r['u'] !== (int) !$index['unique'] || $r['p'] !== null) !== []) {
                throw new DbError("Cannot adopt $table: index {$index['name']} must already have the declared columns and uniqueness, without prefix lengths");
            }
        }
        // Later foreign keys use the schema's BIGINT signedness; never guess the adopted key's type.
        $columns = array_column($this->db->run('SELECT COLUMN_NAME AS n, DATA_TYPE AS t, COLUMN_TYPE AS c FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?', [$table]), null, 'n');
        foreach ($expected['integerColumns'] ?? [] as $column) {
            $actual = $columns[$column['name']] ?? null;
            $type = $column['unsigned'] ? 'BIGINT UNSIGNED' : 'BIGINT';
            if ($actual === null || strtolower($actual['t']) !== 'bigint'
                || str_contains(strtolower($actual['c']), 'unsigned') !== $column['unsigned']) {
                throw new DbError("Cannot adopt $table: column {$column['name']} must use $type");
            }
        }
        foreach ($expected['foreignKeys'] as $key) {
            $actual = $this->db->run('SELECT k.COLUMN_NAME AS c, k.REFERENCED_TABLE_NAME AS t, k.REFERENCED_COLUMN_NAME AS r, r.DELETE_RULE AS d, r.UPDATE_RULE AS u FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.TABLE_NAME = k.TABLE_NAME AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME WHERE k.CONSTRAINT_SCHEMA = DATABASE() AND k.REFERENCED_TABLE_SCHEMA = DATABASE() AND k.TABLE_NAME = ? AND k.CONSTRAINT_NAME = ? ORDER BY k.ORDINAL_POSITION', [$table, $key['name']]);
            $rule = static fn (string $value): string => $value === 'NO ACTION' ? 'RESTRICT' : $value;
            if (count($actual) !== 1 || $actual[0]['c'] !== $key['column'] || $actual[0]['t'] !== $key['table'] || $actual[0]['r'] !== $key['target']
                || $rule($actual[0]['d']) !== $rule($key['onDelete']) || $rule($actual[0]['u']) !== $rule($key['onUpdate'])) {
                throw new DbError("Cannot adopt $table: foreign key {$key['name']} must already have the declared target and actions");
            }
        }
    }

    /**
     * Runs $fn holding a MySQL named lock scoped to this site's database and table prefix, so every
     * writer (first request, activation, `wp typedpress migrate`) applies a given migration once. Waits up
     * to 30 seconds for another holder, then throws rather than letting the caller run on a schema
     * that is still changing.
     */
    public static function locked(Connection $db, string $name, callable $fn, int $seconds = 30): mixed
    {
        return $db->locked('typedpress:' . substr(hash('sha256', DB_NAME . ':' . $db->prefix() . ':' . $name), 0, 40), $seconds, $fn);
    }

    /**
     * Brings storage up to date on a request that found it stale: runs $fn under the lock unless
     * $current() turns true once the lock is held (another request finished first). Returns null
     * when storage is current, or the problem when it isn't: the caller keeps WordPress serving,
     * refuses TypedPress operations, logs, and tells administrators; the next request retries.
     *
     * @param callable(): bool $current
     */
    public static function upgrade(Connection $db, string $name, callable $current, callable $fn): ?string
    {
        try {
            self::locked($db, $name, static function () use ($current, $fn): void {
                if (!$current()) {
                    $fn();
                }
            });

            return null;
        } catch (\Throwable $e) {
            $problem = $e->getMessage();
            error_log('[typedpress] ' . $problem);
            add_action('admin_notices', static function () use ($problem): void {
                if (current_user_can('manage_options')) {
                    printf('<div class="notice notice-error"><p>%s</p></div>', esc_html('TypedPress: ' . $problem));
                }
            });

            return $problem;
        }
    }

    /**
     * The ledger table, created on first use. Rows carry the app's name (`app`, up to the 191
     * characters an index allows; `typedpress build` names are plugin slugs well under that).
     *
     * A ledger from before rows were keyed by app belongs to the one app that ran on the site: its
     * rows go to the app whose `tp_<app>_schema` option exists. With no such app, or several, the
     * owner is unknown and the conversion refuses instead of guessing: replaying another app's
     * history could drop data. Creation and conversion hold one site-wide lock (every app shares the
     * table, so two apps' locks wouldn't serialize them) and re-check after acquiring it.
     */
    public function ledger(): string
    {
        $ledger = $this->table('tp__migrations');
        if ($this->keyed() && $this->hashed()) {
            return $ledger;
        }
        self::locked($this->db, 'tp__migrations', fn () => $this->createOrConvert($ledger));

        return $ledger;
    }

    /** Whether the ledger has the `sql` column (rows recording the hash of what they applied). */
    private function hashed(): bool
    {
        return $this->db->run('SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?', [$this->table('tp__migrations'), 'sql']) !== [];
    }

    /**
     * This app's ledger rows: id, and the hash of the file it applied (null for rows from before the
     * column existed, and for `<id>:<n>` step rows). Read only; empty without a keyed ledger.
     *
     * @return list<array{id: string, sql: ?string}>
     */
    public function history(): array
    {
        if (!$this->keyed()) {
            return [];
        }
        $column = $this->hashed() ? '`sql`' : 'NULL';
        $rows = $this->db->run("SELECT `id`, $column AS `sql` FROM `" . $this->table('tp__migrations') . '` WHERE `app` = ? ORDER BY `id`', [$this->schema->name()]);

        return array_map(static fn (array $r): array => ['id' => (string) $r['id'], 'sql' => $r['sql'] === null ? null : (string) $r['sql']], $rows);
    }

    private function createOrConvert(string $ledger): void
    {
        $exists = $this->db->run('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?', [$ledger]) !== [];
        if (!$exists) {
            $this->db->run("CREATE TABLE `$ledger` (`app` VARCHAR(191) NOT NULL, `id` VARCHAR(191) NOT NULL, `applied_at` CHAR(24) NOT NULL, `sql` CHAR(64) NULL, PRIMARY KEY (`app`, `id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

            return;
        }
        if (!$this->keyed()) {
            $owners = $this->legacyOwners();
            if (count($owners) !== 1) {
                throw new \RuntimeException('the migration ledger predates per-app keys and its owner is unclear (' . ($owners === [] ? 'no app' : implode(', ', $owners)) . "); set its rows' app with: ALTER TABLE `$ledger` ADD COLUMN `app` VARCHAR(191) NOT NULL DEFAULT '<app>' FIRST, DROP PRIMARY KEY, ADD PRIMARY KEY (`app`, `id`)");
            }
            $this->db->run("ALTER TABLE `$ledger` ADD COLUMN `app` VARCHAR(191) NOT NULL DEFAULT '" . esc_sql($owners[0]) . "' FIRST, DROP PRIMARY KEY, ADD PRIMARY KEY (`app`, `id`)");
            $this->db->run("ALTER TABLE `$ledger` ALTER COLUMN `app` DROP DEFAULT");
        }
        if (!$this->hashed()) {
            // Additive: rows already there keep a null hash and count by id only.
            $this->db->run("ALTER TABLE `$ledger` ADD COLUMN `sql` CHAR(64) NULL");
        }
    }

    /** Whether the ledger exists and is keyed by app (false for a missing or pre-key ledger). */
    public function keyed(): bool
    {
        return $this->db->run('SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?', [$this->table('tp__migrations'), 'app']) !== [];
    }

    /** @return list<string> apps with a recorded schema hash on this site */
    private function legacyOwners(): array
    {
        $options = $this->db->wpdb()->options;
        $owners = [];
        foreach ($this->db->run("SELECT `option_name` AS n FROM `$options` WHERE `option_name` LIKE 'tp\\_%\\_schema'") as $row) {
            if (preg_match('/^tp_(.+)_schema$/', (string) $row['n'], $m)) {
                $owners[] = $m[1];
            }
        }

        return $owners;
    }

    /**
     * This app's ids in a ledger from before rows were keyed by app, without converting it: the rows
     * are this app's only when it is the ledger's one owner, as ledger() decides. With no ledger, or
     * another owner, nothing is recorded for this app yet (ledger() then creates or refuses).
     *
     * @return list<string>
     */
    private function unkeyedDone(): array
    {
        $ledger = $this->table('tp__migrations');
        if ($this->db->run('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?', [$ledger]) === []
            || $this->legacyOwners() !== [$this->schema->name()]) {
            return [];
        }

        return array_column($this->db->run("SELECT `id` FROM `$ledger`"), 'id');
    }

    /** @return list<string> this app's recorded ids, sorted (for comparing ledger states) */
    public function applied(): array
    {
        $done = $this->done();
        sort($done, SORT_STRING);

        return $done;
    }

    /** @return list<string> this app's recorded ids (files and in-progress `<id>:<n>` steps) */
    private function done(): array
    {
        return array_column($this->db->run('SELECT `id` FROM `' . $this->table('tp__migrations') . '` WHERE `app` = ?', [$this->schema->name()]), 'id');
    }

    public function pending(): array
    {
        $done = $this->keyed() ? $this->done() : [];
        $files = array_map(static fn (string $file): string => basename($file, '.sql'), glob($this->dir . '/*.sql') ?: []);
        sort($files, SORT_STRING);
        return array_values(array_diff($files, $done));
    }

    /**
     * Tables that must be InnoDB but aren't: core posts/postmeta and every `{prefix}tp_*` table.
     *
     * @return list<string>
     */
    public function nonInnoDb(): array
    {
        $wpdb = $this->db->wpdb();
        // Users join TypedPress's transactions too (auth collections and guests, §6.2): check them always.
        $names = [$wpdb->posts, $wpdb->postmeta, $wpdb->users, $wpdb->usermeta];
        foreach ($this->schema->collections() as $spec) {
            if (isset($spec['existingTable'])) {
                $names[] = $spec['existingTable'];
            }
        }
        $placeholders = implode(', ', array_fill(0, count($names), '?'));
        $rows = $this->db->run(
            'SELECT TABLE_NAME AS t, ENGINE AS e, TABLE_COLLATION AS c FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND (TABLE_NAME IN (' . $placeholders . ') OR TABLE_NAME LIKE ?)',
            [...$names, $wpdb->esc_like($this->db->prefix() . 'tp_') . '%'],
        );
        $bad = [];
        foreach ($rows as $r) {
            if (strcasecmp((string) $r['e'], 'InnoDB') !== 0 || !str_starts_with(strtolower((string) $r['c']), 'utf8mb4_')) {
                $bad[] = (string) $r['t'];
            }
        }

        return $bad;
    }

    private function table(string $name): string
    {
        return $this->db->prefix() . $name;
    }
}
